def add_maquinaria(apps, schema_editor):
    Company = apps.get_model("ivr_config", "Company")
    Template = apps.get_model("panel", "ScreenExportTemplate")
    for company in Company.objects.all():
        Template.objects.get_or_create(
            company=company, screen="fleet", is_global=True,
            name="MAQUINARIA (Excel de Yolanda)",
            defaults={"columns": FLEET_MAQUINARIA},
        )


